  void ShowGames(){var p=peers.SelectedItem as Item;string pair=p==null?"":Wire.Text(p.Row,"pairId"),key=p==null?"":pair+":"+Wire.Text(p.Row,"connectionGeneration")+":"+Wire.Text(p.Row,"catalogueVersion");if(key==displayedKey)return;if(displayedPair.Length>0)checkedByPeer[displayedPair]=new HashSet<int>(games.CheckedItems.Cast<Item>().Select(g=>Convert.ToInt32(g.Row["gameId"])));int top=pair==displayedPair?games.TopIndex:0;HashSet<int> selected;if(!checkedByPeer.TryGetValue(pair,out selected))selected=new HashSet<int>();games.BeginUpdate();games.Items.Clear();if(p!=null)foreach(var raw in Rows(p.Row,"games")){var row=Wire.Map(raw);games.Items.Add(new Item{Row=row,Caption=Wire.Text(row,"name")},selected.Contains(Convert.ToInt32(row["gameId"])));}if(games.Items.Count>0)games.TopIndex=Math.Min(Math.Max(0,top),games.Items.Count-1);games.EndUpdate();displayedPair=pair;displayedKey=key;UpdateEnabled();}
  void RenderActivity(Dictionary<string,object> state){string text=String.Join(Environment.NewLine,Rows(state,"activity").Select(raw=>{var row=Wire.Map(raw);DateTime time;return (DateTime.TryParse(Wire.Text(row,"utc"),null,System.Globalization.DateTimeStyles.RoundtripKind,out time)?time.ToLocalTime().ToString("HH:mm:ss"):"")+"  "+Wire.Text(row,"message");}));if(text==lastActivityText)return;lastActivityText=text;transferLog.Text=text;transferLog.SelectionStart=transferLog.TextLength;transferLog.ScrollToCaret();}
