  }
  Dictionary<string,object> CallAgent(object command,int timeout=95000){
#if SHARING_TESTS
   if(fixtureRoot!=null)return ShareClient.CallAt(fixtureRoot,command,timeout);
#endif
   return ShareClient.Call(command,timeout);
  }
